"use strict";

let mainContent;

// Apply layouts on every radio click, including clicks on the selected option.
// An expanded icon rail can then be collapsed without changing layouts first.
document.addEventListener('click', (event) => {
    const layoutOptions = {
        'switcher-layout-default': 'default',
        'switcher-layout-dual': 'dualmenu',
        'switcher-layout-header': 'header',
        'switcher-layout-icons': 'icon-menu',
    };
    const layout = layoutOptions[event.target?.id];
    if (layout && event.target.checked) setSidebarCustomizerLayout(layout);
});

(function () {
    let html = document.querySelector('html');
    mainContent = document.querySelector('.main-content');
    localStorageBackup2();
    customizermainfunction();
    checkOptions();
    setTimeout(() => {
        checkOptions();
    }, 1000);

})();

// Bind controls by responsibility rather than keeping a variable for every input.
function customizermainfunction() {
    const root = document.documentElement;
    const input = id => document.getElementById(id);
    const bind = (id, action) => input(id).addEventListener('click', action);
    const store = (values, removed = []) => {
        Object.entries(values).forEach(([key, value]) => localStorage.setItem(key, value));
        removed.forEach(key => localStorage.removeItem(key));
    };
    const select = ids => ids.forEach(id => { input(id).checked = true; });

    const palettes = [
        ['switcher-background', '18, 28, 49', '29, 42, 67'],
        ['switcher-background1', '41, 29, 64', '56, 39, 78'],
        ['switcher-background2', '16, 47, 62', '25, 64, 79'],
        ['switcher-background3', '49, 33, 27', '67, 48, 40'],
        ['switcher-background4', '20, 49, 39', '31, 68, 55'],
    ];
    palettes.forEach(([id, base, surface]) => bind(id, () => {
        store({AumaUIThemeMode: 'dark', bodyBgRGB: base, bodylightRGB: surface, AumaUIMenu: 'dark', AumaUIHeader: 'dark'});
        ['theme', 'menu', 'header'].forEach(area => root.setAttribute(`data-${area}-color`, 'dark'));
        const variables = {
            '--theme-body-bg-rgb': base,
            '--theme-body-bg-rgb2': surface,
            '--theme-light-rgb': surface,
            '--theme-form-control-bg': `rgb(${surface})`,
            '--theme-input-border': 'rgba(255,255,255,0.1)',
            '--theme-gray-3': 'rgba(255,255,255,0.1)',
        };
        Object.entries(variables).forEach(([key, value]) => root.style.setProperty(key, value));
        select(['switcher-dark-theme', 'switcher-menu-dark', 'switcher-header-dark']);
    }));

    const themeActions = {
        light() {
            lightFn();
            store({AumaUIHeader: 'light'}, ['bodylightRGB', 'bodyBgRGB', 'AumaUIMenu']);
            if (root.getAttribute('data-sidebar-layout') === 'horizontal') root.setAttribute('data-header-color', 'transparent');
        },
        dark() {
            darkFn();
            store({AumaUIMenu: 'dark', AumaUIHeader: 'transparent'});
            if (root.getAttribute('data-sidebar-layout') === 'horizontal') root.setAttribute('data-header-color', 'dark');
        },
    };
    Object.entries(themeActions).forEach(([mode, action]) => bind(`switcher-${mode}-theme`, action));

    [['menu', 'AumaUIMenu'], ['header', 'AumaUIHeader']].forEach(([area, key]) => {
        ['light', 'dark', 'transparent'].forEach(color => bind(`switcher-${area}-${color}`, () => {
            root.setAttribute(`data-${area}-color`, color);
            store({[key]: color});
        }));
    });
    ['header', 'menu'].forEach(area => {
        const prefix = 'AumaUI' + area;
        [['fixed', 'fixed', 'scrollable'], ['scroll', 'scrollable', 'fixed']].forEach(([id, position, opposite]) => {
            bind(`switcher-${area}-${id}`, () => {
                root.setAttribute(`data-${area}-position`, position);
                store({[prefix + position]: true}, [prefix + opposite]);
            });
        });
    });

    ['rtl', 'ltr'].forEach(direction => bind(`switcher-${direction}`, () => {
        const rtl = direction === 'rtl';
        store({[rtl ? 'AumaUIrtl' : 'AumaUIltr']: true}, [rtl ? 'AumaUIltr' : 'AumaUIrtl']);
        if (rtl) rtlFn();
        else ltrFn();
        if (document.querySelector('.noUi-target')) {
            document.querySelectorAll('.noUi-origin').forEach(origin => origin.classList.toggle('transform-none', rtl));
        }
    }));

    bind('reset-all', () => {
        ResetAllFn();
        window.MetraSidenav.setNavActive();
        select(['switcher-menu-transparent']);
        document.querySelectorAll('.sidenav-item').forEach(item => {
            if (item.classList.contains('open') && !item.classList.contains('active')) item.querySelector('ul').style.display = 'none';
        });
    });
    ['enable', 'disable'].forEach(mode => {
        input(`switcher-loader-${mode}`).onclick = () => {
            root.setAttribute('loader', mode);
            store({loaderEnable: mode === 'enable' ? 'true' : 'false'});
        };
    });
}

function ltrFn() {
    let html = document.querySelector('html')
    if (!document.querySelector("#style").href.includes('bootstrap.min.css')) {
        document.querySelector("#style")?.setAttribute("href", "../assets/libs/bootstrap/css/bootstrap.min.css");
    }
    html.setAttribute("dir", "ltr");
    document.querySelector('#switcher-ltr').checked = true;
    checkOptions();
}

function rtlFn() {
    let html = document.querySelector('html');
    html.setAttribute("dir", "rtl");
    document.querySelector("#style")?.setAttribute("href", "../assets/libs/bootstrap/css/bootstrap.rtl.min.css");
    checkOptions();
}

function lightFn() {
    let html = document.querySelector('html');
    html.setAttribute('data-theme-color', 'light');
    html.setAttribute('data-header-color', 'transparent');
    html.setAttribute('data-menu-color', 'transparent');
    if (!localStorage.getItem('primaryRGB')) {
        html.setAttribute('style', '')
    }
    document.querySelector('#switcher-light-theme').checked = true;
    document.querySelector('#switcher-menu-transparent').checked = true;
    document.querySelector('#switcher-header-transparent').checked = true;
    localStorage.removeItem("AumaUIdarktheme");
    localStorage.setItem("AumaUIThemeMode", "light");
    localStorage.removeItem("AumaUIbgColor");
    localStorage.removeItem("AumaUIheaderbg");
    localStorage.removeItem("AumaUIbgwhite");
    localStorage.removeItem("AumaUImenubg");
    localStorage.removeItem("AumaUImenubg");
    checkOptions();
    html.style.removeProperty('--theme-body-bg-rgb');
    html.style.removeProperty('--theme-body-bg-rgb2');
    html.style.removeProperty("--theme-light-rgb");
    html.style.removeProperty("--theme-form-control-bg");
    html.style.removeProperty("--theme-gray-3");
    html.style.removeProperty("--theme-input-border");

    document.querySelector("#switcher-background4").checked = false
    document.querySelector("#switcher-background3").checked = false
    document.querySelector("#switcher-background2").checked = false
    document.querySelector("#switcher-background1").checked = false
    document.querySelector("#switcher-background").checked = false
    document.querySelector('#switcher-menu-transparent').checked = true;
    document.querySelector('#switcher-header-transparent').checked = true;

}

function darkFn() {
    let html = document.querySelector('html');
    html.setAttribute('data-theme-color', 'dark');
    html.setAttribute('data-header-color', 'transparent');
    html.setAttribute('data-menu-color', 'dark');
    if (!localStorage.getItem('primaryRGB')) {
        html.setAttribute('style', '')
    }
    document.querySelector('#switcher-menu-dark').checked = true;
    document.querySelector('#switcher-header-dark').checked = true;
    document.querySelector('html').style.removeProperty('--theme-body-bg-rgb');
    document.querySelector('html').style.removeProperty('--theme-body-bg-rgb2');
    document.querySelector('html').style.removeProperty('--theme-light-rgb');
    document.querySelector('html').style.removeProperty('--theme-form-control-bg');
    document.querySelector('html').style.removeProperty('--theme-gray-3');
    document.querySelector('html').style.removeProperty('--theme-input-border');
    localStorage.setItem("AumaUIdarktheme", true);
    localStorage.setItem("AumaUIThemeMode", "dark");
    localStorage.removeItem("AumaUIlighttheme");
    localStorage.removeItem("bodyBgRGB");
    localStorage.removeItem("AumaUIbgColor");
    localStorage.removeItem("AumaUIheaderbg");
    localStorage.removeItem("AumaUIbgwhite");
    localStorage.removeItem("AumaUImenubg");
    checkOptions();

    document.querySelector("#switcher-background4").checked = false
    document.querySelector("#switcher-background3").checked = false
    document.querySelector("#switcher-background2").checked = false
    document.querySelector("#switcher-background1").checked = false
    document.querySelector("#switcher-background").checked = false
    document.querySelector('#switcher-menu-transparent').checked = true;
    document.querySelector('#switcher-header-transparent').checked = true;
}

function horizontalClickFn() {
    let html = document.querySelector('html');
    html.setAttribute('data-sidebar-layout', 'horizontal');
    html.removeAttribute('data-vertical-style');
    if (!html.getAttribute('data-nav-style')) {
        html.setAttribute('data-nav-style', 'menu-click');
    }
    if (!localStorage.AumaUIMenu && !localStorage.bodylightRGB) {
        html.setAttribute("data-menu-color", "transparent")
        document.querySelector('#switcher-menu-transparent').checked = true;
        checkOptions();
    }
    checkOptions();
    window.MetraSidenav.checkHoriMenu();
}

function setSidebarCustomizerLayout(layout) {
    const html = document.documentElement;
    const mainMenu = document.querySelector('.sidenav-list');
    document.getElementById('responsive-overlay')?.classList.remove('active');
    document.querySelectorAll('.sidenav-submenu.double-menu-active').forEach((menu) => {
        menu.classList.remove('double-menu-active');
    });
    localStorage.removeItem('AumaUIiconmenu');

    if (layout === 'header') {
        localStorage.setItem('AumaUIlayout', 'horizontal');
        localStorage.removeItem('AumaUIverticalstyles');
        html.removeAttribute('data-vertical-style');
        html.removeAttribute('data-icon-overlay');
        html.removeAttribute('data-icon-text');
        html.removeAttribute('data-layout-style');
        if (window.innerWidth < 992) html.setAttribute('data-toggled', 'close');
        else html.removeAttribute('data-toggled');
        horizontalClickFn();
        window.MetraSidenav.clearNavDropdown();
        mainContent?.addEventListener('click', window.MetraSidenav.clearNavDropdown);
    } else {
        localStorage.removeItem('AumaUIlayout');
        localStorage.setItem('AumaUIverticalstyles', layout);
        html.setAttribute('data-sidebar-layout', 'vertical');
        html.removeAttribute('data-nav-style');
        html.removeAttribute('data-icon-overlay');
        html.removeAttribute('data-icon-text');
        html.removeAttribute('data-toggled');

        if (layout === 'dualmenu') {
            html.removeAttribute('data-vertical-style');
            html.setAttribute('data-layout-style', 'dualmenu');
            // Restore the active item after clearing any submenu from the old layout.
            window.MetraSidenav.setNavActive();
            html.setAttribute('data-toggled', 'dual-menu-close');
            window.MetraSidenav.toggleSidemenu();
            if (window.innerWidth >= 992) {
                const activeCategory = document.querySelector(
                    '.sidenav-list > li.active.has-submenu > .sidenav-link'
                ) || document.querySelector('.sidenav-list > li.has-submenu > .sidenav-link');
                const activePanel = activeCategory?.nextElementSibling;

                if (activePanel?.matches('.sidenav-submenu')) {
                    document.querySelectorAll('.sidenav-list > li > .sidenav-submenu.double-menu-active').forEach((menu) => {
                        menu.classList.remove('double-menu-active');
                    });
                    activePanel.classList.add('double-menu-active');
                    html.setAttribute('data-toggled', 'dual-menu-open');
                }
            }
        } else if (layout === 'icon-menu') {
            html.removeAttribute('data-layout-style');
            localStorage.setItem('AumaUIverticalstyles', 'overlay');
            localStorage.removeItem('AumaUIiconmenu');
            html.setAttribute('data-vertical-style', 'overlay');
            // Use the existing icon-overlay behavior: a collapsed icon rail
            // that expands on hover and can also be opened from the header toggle.
            window.MetraSidenav.toggleSidemenu();
            window.MetraSidenav.setNavActive();
        } else {
            html.removeAttribute('data-layout-style');
            html.removeAttribute('data-vertical-style');
            if (window.innerWidth >= 992) window.MetraSidenav.toggleSidemenu();
            html.setAttribute('data-vertical-style', 'default');
            if (window.innerWidth < 992) html.setAttribute('data-toggled', 'close');
            else html.removeAttribute('data-toggled');
        }

        mainContent?.removeEventListener('click', window.MetraSidenav.clearNavDropdown);
        if (mainMenu) {
            mainMenu.style.marginLeft = '0px';
            mainMenu.style.marginRight = '0px';
        }
        window.MetraSidenav.setNavActive();
        if (layout === 'icon-menu') {
            // Keep the rail collapsed immediately after active-menu
            // normalization; startup applies this state during refresh too.
            html.removeAttribute('data-icon-overlay');
            html.setAttribute(
                'data-toggled',
                window.innerWidth >= 992 ? 'icon-overlay-close' : 'close'
            );
        }
    }

    checkOptions();
}


function ResetAllFn() {
    let html = document.querySelector('html');
    if (localStorage.getItem("AumaUIlayout") == "horizontal") {
        document.querySelector(".sidenav-list").style.display = "block"
    }
    checkOptions();

    // clearing localstorage
    localStorage.clear();

    // Reset the workspace to light mode with a dark sidebar surface.
    lightFn();
    html.setAttribute('data-menu-color', 'dark');
    localStorage.setItem('AumaUIMenu', 'dark');
    document.querySelector('#switcher-menu-dark').checked = true;
    document.querySelector('#switcher-menu-transparent').checked = false;

    //To reset the light-rgb
    document.querySelector('html').removeAttribute("style")

    // Clear remaining legacy layout attributes.
    html.removeAttribute('data-nav-style');
    html.removeAttribute('data-menu-position');
    html.removeAttribute('data-header-position');

    // removing theme styles

    // clear primary & bg color
    html.style.removeProperty(`--theme-primary-rgb`);
    html.style.removeProperty(`--theme-body-bg-rgb`);

    // reseting to ltr
    ltrFn();

    // Reset the customizer to the default sidebar layout.
    setSidebarCustomizerLayout('default');
    // html.setAttribute("data-toggled", "dual-menu-close");
    mainContent.removeEventListener('click', window.MetraSidenav.clearNavDropdown);

    // reseting menu position styles
    document.querySelector('#switcher-menu-fixed').checked = true;
    document.querySelector('#switcher-menu-scroll').checked = false;

    // reseting header position styles
    document.querySelector('#switcher-header-fixed').checked = true;
    document.querySelector('#switcher-header-scroll').checked = false;


    // resetting theme background
    document.querySelector("#switcher-background").checked = false
    document.querySelector("#switcher-background1").checked = false
    document.querySelector("#switcher-background2").checked = false
    document.querySelector("#switcher-background3").checked = false
    document.querySelector("#switcher-background4").checked = false

    // to reset horizontal menu scroll
    document.querySelector(".sidenav-list").style.marginLeft = "0px"
    document.querySelector(".sidenav-list").style.marginRight = "0px"
}

function checkOptions() {

    // dark
    if (localStorage.getItem('AumaUIdarktheme')) {
        document.querySelector('#switcher-dark-theme').checked = true;
    }

    //RTL
    if (localStorage.getItem('AumaUIrtl')) {
        document.querySelector('#switcher-rtl').checked = true;
    }
    else {
        document.querySelector('#switcher-ltr').checked = true;
    }

    // Resolve saved surface selections using the existing radio IDs.
    const savedSurfaces = [
        ['AumaUIHeader', 'header'],
        ['AumaUIMenu', 'menu'],
    ];
    savedSurfaces.forEach(([key, surface]) => {
        const value = localStorage.getItem(key);
        if (['light', 'dark', 'transparent'].includes(value)) {
            document.querySelector(`#switcher-${surface}-${value}`).checked = true;
        }
    });

    const savedPositions = [
        ['AumaUIheaderscrollable', 'switcher-header-scroll'],
        ['AumaUImenuscrollable', 'switcher-menu-scroll'],
        ['AumaUIheaderfixed', 'switcher-header-fixed'],
        ['AumaUImenufixed', 'switcher-menu-fixed'],
    ];
    savedPositions.forEach(([key, id]) => {
        if (localStorage.getItem(key)) document.getElementById(id).checked = true;
    });

    const headerOnly = localStorage.getItem('AumaUIlayout') === 'horizontal';
    const storedSidebarStyle = localStorage.getItem('AumaUIverticalstyles') || 'default';
    const verticalStyle = storedSidebarStyle === 'doublemenu' ? 'dualmenu' : storedSidebarStyle;
    document.querySelector('#switcher-layout-header').checked = headerOnly;
    document.querySelector('#switcher-layout-default').checked = !headerOnly && verticalStyle === 'default';
    document.querySelector('#switcher-layout-dual').checked = !headerOnly && verticalStyle === 'dualmenu';
    document.querySelector('#switcher-layout-icons').checked = !headerOnly && (localStorage.getItem('AumaUIiconmenu') === 'icon-click' || verticalStyle === 'overlay');
    // loader
    if (localStorage.loaderEnable != "true") {
        document.querySelector("#switcher-loader-disable").checked = true
    }
}

function localStorageBackup2() {
    if (localStorage.bodyBgRGB || localStorage.bodylightRGB) {
        document.querySelector('#switcher-dark-theme').checked = true;
        document.querySelector('#switcher-menu-dark').checked = true;
        document.querySelector('#switcher-header-transparent').checked = true;
    }

    if (localStorage.bodyBgRGB && localStorage.bodylightRGB) {
        const storedPalettes = [
            ['18, 28, 49', 'switcher-background'],
            ['41, 29, 64', 'switcher-background1'],
            ['16, 47, 62', 'switcher-background2'],
            ['49, 33, 27', 'switcher-background3'],
            ['20, 49, 39', 'switcher-background4'],
        ];
        storedPalettes.forEach(([color, id]) => {
            if (localStorage.bodyBgRGB == color) document.getElementById(id).checked = true;
        });
    }

    if (localStorage.loaderEnable == "true") {
        document.querySelector("#switcher-loader-enable").checked = true
    }
}


